        "0", "A", 9,
        "0", "B", 10,
        "0", "C", 11,
        "0", "A", 12,
        "0", "B", 13,
        "0", "C", 14,
        "0", "A", 15,
        "0", "B", 16,
        "0", "C", 17,
        "0", "A", 18,
        "0", "B", 19,
        "0", "C", 20,
        "0", "A", 21,
