};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grid1_header3', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#grid1_header4', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[1].checked == false;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[2].checked == false;
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[3].checked == false;
}
scwin.checkVal4 = function() {
    return WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[4].checked == false;
}
scwin.checkVal5 = function() {
    return WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[1].checked == true;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 '분류2'항목과 '금액'항목을 groupby 시킨다.
    //1. After executing the sample, group the item 'Classification 2' and 'Amount'.
    //Verify step 1. The 'Category 2' and 'Amount' items are grouped.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == '분류2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_body_tbody tr').not('.w2grid_hidedRow').length == 6", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_1_0').text() == '6'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_3_0').text() == '10'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_5_0').text() == '10'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 2", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value')[1].innerText == '금액'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_2_0').text() == '1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_4_0').text() == '2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_6_0').text() == '3'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_7_0').text() == '6'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_cell_10_0').text() == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. groupby되어진 '분류2'항목을 클릭하여 '전체선택'을 체크해제하고 '금액'항목을 클릭하여 '전체선택'을 체크하고 체크해제한다.(2번클릭)
    //2. Click the 'Group 2' item in the 'Group 2' box to uncheck 'Select all' and click the 'Amount' item to check the 'Select all'
    //Verify step 2. Make sure there is no data.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
    //Test step 3. '분류2'항목을 클릭하여 전체리스트가 보여지는지를 점검한다.
    //3. Click the 'Category 2' item to check if the entire list is displayed.
    //Verify step 3. The entire list (full selection, A, B, C) is displayed.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_list_listColumn_checkbox')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column')[0].click()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_groupbyZone_list').css('height') == '105px'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //formatter
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 30-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
